#!/usr/bin/env python3
"""Setup script — Portal CREAR. Ejecutar desde cualquier carpeta."""
import os, sys

BASE = "portal-crear"
if os.path.exists(BASE):
    print(f"Error: la carpeta '{BASE}' ya existe. Borrarla o elegir otra ubicación.")
    sys.exit(1)

FILES = {
  "src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n@layer base {\n  body {\n    font-family: 'Inter', system-ui, sans-serif;\n    background-color: #F4F2FF;\n    color: #1E1B4B;\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n    margin: 0;\n  }\n  #root {\n    min-height: 100svh;\n  }\n  *::-webkit-scrollbar { width: 4px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb { background: #C4B5FD; border-radius: 99px; }\n}\n\n.pb-safe { padding-bottom: max(env(safe-area-inset-bottom), 16px); }\n.pt-safe { padding-top: env(safe-area-inset-top, 0px); }\n",
  "src/App.jsx": "import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom'\nimport { AuthProvider, useAuth } from './context/AuthContext'\nimport TopBar from './components/TopBar'\nimport BottomNav from './components/BottomNav'\nimport Login from './pages/Login'\nimport Home from './pages/Home'\nimport Pagos from './pages/Pagos'\nimport Asistencia from './pages/Asistencia'\nimport Grupos from './pages/Grupos'\nimport Evaluaciones from './pages/Evaluaciones'\n\nconst pageTitles = {\n  '/home':         'Inicio',\n  '/pagos':        'Pagos',\n  '/asistencia':   'Asistencia',\n  '/grupos':       'Mis grupos',\n  '/evaluaciones': 'Evaluaciones',\n}\n\nfunction ProtectedLayout() {\n  const { alumno } = useAuth()\n  const path = window.location.pathname\n  if (!alumno) return <Navigate to=\"/login\" replace />\n  return (\n    <div className=\"flex flex-col h-svh max-w-md mx-auto\">\n      <TopBar title={pageTitles[path] ?? 'CREAR'} />\n      <main className=\"flex-1 overflow-y-auto bg-primary-subtle\">\n        <Routes>\n          <Route path=\"/home\"         element={<Home />} />\n          <Route path=\"/pagos\"        element={<Pagos />} />\n          <Route path=\"/asistencia\"   element={<Asistencia />} />\n          <Route path=\"/grupos\"       element={<Grupos />} />\n          <Route path=\"/evaluaciones\" element={<Evaluaciones />} />\n          <Route path=\"*\"             element={<Navigate to=\"/home\" replace />} />\n        </Routes>\n      </main>\n      <BottomNav />\n    </div>\n  )\n}\n\nfunction PublicRoute() {\n  const { alumno } = useAuth()\n  if (alumno) return <Navigate to=\"/home\" replace />\n  return <Login />\n}\n\nexport default function App() {\n  return (\n    <AuthProvider>\n      <BrowserRouter>\n        <Routes>\n          <Route path=\"/login\" element={<PublicRoute />} />\n          <Route path=\"/*\"     element={<ProtectedLayout />} />\n        </Routes>\n      </BrowserRouter>\n    </AuthProvider>\n  )\n}\n",
  "src/App.css": ".counter {\n  font-size: 16px;\n  padding: 5px 10px;\n  border-radius: 5px;\n  color: var(--accent);\n  background: var(--accent-bg);\n  border: 2px solid transparent;\n  transition: border-color 0.3s;\n  margin-bottom: 24px;\n\n  &:hover {\n    border-color: var(--accent-border);\n  }\n  &:focus-visible {\n    outline: 2px solid var(--accent);\n    outline-offset: 2px;\n  }\n}\n\n.hero {\n  position: relative;\n\n  .base,\n  .framework,\n  .vite {\n    inset-inline: 0;\n    margin: 0 auto;\n  }\n\n  .base {\n    width: 170px;\n    position: relative;\n    z-index: 0;\n  }\n\n  .framework,\n  .vite {\n    position: absolute;\n  }\n\n  .framework {\n    z-index: 1;\n    top: 34px;\n    height: 28px;\n    transform: perspective(2000px) rotateZ(300deg) rotateX(44deg) rotateY(39deg)\n      scale(1.4);\n  }\n\n  .vite {\n    z-index: 0;\n    top: 107px;\n    height: 26px;\n    width: auto;\n    transform: perspective(2000px) rotateZ(300deg) rotateX(40deg) rotateY(39deg)\n      scale(0.8);\n  }\n}\n\n#center {\n  display: flex;\n  flex-direction: column;\n  gap: 25px;\n  place-content: center;\n  place-items: center;\n  flex-grow: 1;\n\n  @media (max-width: 1024px) {\n    padding: 32px 20px 24px;\n    gap: 18px;\n  }\n}\n\n#next-steps {\n  display: flex;\n  border-top: 1px solid var(--border);\n  text-align: left;\n\n  & > div {\n    flex: 1 1 0;\n    padding: 32px;\n    @media (max-width: 1024px) {\n      padding: 24px 20px;\n    }\n  }\n\n  .icon {\n    margin-bottom: 16px;\n    width: 22px;\n    height: 22px;\n  }\n\n  @media (max-width: 1024px) {\n    flex-direction: column;\n    text-align: center;\n  }\n}\n\n#docs {\n  border-right: 1px solid var(--border);\n\n  @media (max-width: 1024px) {\n    border-right: none;\n    border-bottom: 1px solid var(--border);\n  }\n}\n\n#next-steps ul {\n  list-style: none;\n  padding: 0;\n  display: flex;\n  gap: 8px;\n  margin: 32px 0 0;\n\n  .logo {\n    height: 18px;\n  }\n\n  a {\n    color: var(--text-h);\n    font-size: 16px;\n    border-radius: 6px;\n    background: var(--social-bg);\n    display: flex;\n    padding: 6px 12px;\n    align-items: center;\n    gap: 8px;\n    text-decoration: none;\n    transition: box-shadow 0.3s;\n\n    &:hover {\n      box-shadow: var(--shadow);\n    }\n    .button-icon {\n      height: 18px;\n      width: 18px;\n    }\n  }\n\n  @media (max-width: 1024px) {\n    margin-top: 20px;\n    flex-wrap: wrap;\n    justify-content: center;\n\n    li {\n      flex: 1 1 calc(50% - 8px);\n    }\n\n    a {\n      width: 100%;\n      justify-content: center;\n      box-sizing: border-box;\n    }\n  }\n}\n\n#spacer {\n  height: 88px;\n  border-top: 1px solid var(--border);\n  @media (max-width: 1024px) {\n    height: 48px;\n  }\n}\n\n.ticks {\n  position: relative;\n  width: 100%;\n\n  &::before,\n  &::after {\n    content: '';\n    position: absolute;\n    top: -4.5px;\n    border: 5px solid transparent;\n  }\n\n  &::before {\n    left: 0;\n    border-left-color: var(--border);\n  }\n  &::after {\n    right: 0;\n    border-right-color: var(--border);\n  }\n}\n",
  "src/main.jsx": "import { createRoot } from 'react-dom/client'\nimport './index.css'\nimport App from './App.jsx'\n\ncreateRoot(document.getElementById('root')).render(<App />)\n",
  "src/components/BottomNav.jsx": "import { NavLink } from 'react-router-dom'\nimport { Home, CreditCard, CalendarCheck, UsersRound, Star } from 'lucide-react'\n\nconst items = [\n  { to: '/home',        icon: Home,         label: 'Inicio' },\n  { to: '/pagos',       icon: CreditCard,   label: 'Pagos' },\n  { to: '/asistencia',  icon: CalendarCheck,label: 'Asistencia' },\n  { to: '/grupos',      icon: UsersRound,   label: 'Grupos' },\n  { to: '/evaluaciones',icon: Star,         label: 'Notas' },\n]\n\nexport default function BottomNav() {\n  return (\n    <nav className=\"bg-white border-t border-[#EDE9FE] pb-safe shrink-0\">\n      <div className=\"flex\">\n        {items.map(({ to, icon: Icon, label }) => (\n          <NavLink key={to} to={to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-1 py-2.5 transition-colors ${\n                isActive ? 'text-primary' : 'text-[#A89FC8]'\n              }`\n            }\n          >\n            {({ isActive }) => (\n              <>\n                <div className={`p-1.5 rounded-xl transition-colors ${isActive ? 'bg-primary-light' : ''}`}>\n                  <Icon size={18} />\n                </div>\n                <span className=\"text-[10px] font-semibold leading-none\">{label}</span>\n              </>\n            )}\n          </NavLink>\n        ))}\n      </div>\n    </nav>\n  )\n}\n",
  "src/components/TopBar.jsx": "import { LogOut } from 'lucide-react'\nimport { useAuth } from '../context/AuthContext'\nimport { useNavigate } from 'react-router-dom'\n\nexport default function TopBar({ title }) {\n  const { alumno, logout } = useAuth()\n  const navigate = useNavigate()\n\n  function handleLogout() {\n    logout()\n    navigate('/login', { replace: true })\n  }\n\n  return (\n    <header className=\"bg-white border-b border-[#EDE9FE] px-4 h-14 flex items-center justify-between shrink-0 sticky top-0 z-10\">\n      <div className=\"flex items-center gap-2.5\">\n        <div className=\"w-7 h-7 rounded-lg flex items-center justify-center shrink-0\"\n          style={{ background: 'linear-gradient(135deg, #7C3AED, #A78BFA)' }}>\n          <span className=\"text-white text-[10px] font-black\">C</span>\n        </div>\n        <span className=\"text-sm font-bold text-[#1E1B4B]\">{title}</span>\n      </div>\n\n      <div className=\"flex items-center gap-2\">\n        {alumno && (\n          <span className=\"text-xs text-[#A89FC8] hidden sm:block\">\n            {alumno.apellido}, {alumno.nombre}\n          </span>\n        )}\n        <button onClick={handleLogout}\n          className=\"w-8 h-8 flex items-center justify-center rounded-xl text-[#A89FC8] hover:bg-[#F4F2FF] hover:text-primary transition-colors\">\n          <LogOut size={15} />\n        </button>\n      </div>\n    </header>\n  )\n}\n",
  "src/components/ui/Badge.jsx": "const COLORS = {\n  green:  { cls: 'bg-emerald-50 text-emerald-700 ring-1 ring-emerald-200', dot: 'bg-emerald-400' },\n  red:    { cls: 'bg-red-50 text-red-600 ring-1 ring-red-200',             dot: 'bg-red-400' },\n  yellow: { cls: 'bg-amber-50 text-amber-700 ring-1 ring-amber-200',       dot: 'bg-amber-400' },\n  blue:   { cls: 'bg-primary-light text-primary ring-1 ring-purple-200',   dot: 'bg-primary' },\n  teal:   { cls: 'bg-teal-light text-teal-dark ring-1 ring-teal/30',       dot: 'bg-teal' },\n  gray:   { cls: 'bg-gray-100 text-gray-500 ring-1 ring-gray-200',         dot: 'bg-gray-400' },\n}\n\nexport default function Badge({ children, color = 'gray', dot = false, className = '' }) {\n  const { cls, dot: dotColor } = COLORS[color] ?? COLORS.gray\n  return (\n    <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold ${cls} ${className}`}>\n      {dot && <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${dotColor}`} />}\n      {children}\n    </span>\n  )\n}\n",
  "src/components/ui/Spinner.jsx": "export default function Spinner({ className = '' }) {\n  return (\n    <div className={`flex justify-center items-center ${className}`}>\n      <div className=\"w-8 h-8 border-[3px] border-primary-light border-t-primary rounded-full animate-spin\" />\n    </div>\n  )\n}\n",
  "src/services/portal.js": "import { supabase } from '../lib/supabase'\n\nexport async function getCuotas(alumnoId) {\n  const { data, error } = await supabase\n    .from('cuotas')\n    .select('id, mes, monto, estado, fecha_vencimiento, fecha_pago')\n    .eq('alumno_id', alumnoId)\n    .order('mes', { ascending: false })\n  if (error) throw error\n  return data ?? []\n}\n\nexport async function getInscripciones(alumnoId) {\n  const { data: insc, error } = await supabase\n    .from('inscripciones')\n    .select('id, estado, fecha, grupo_id')\n    .eq('alumno_id', alumnoId)\n    .eq('estado', 'activa')\n  if (error) throw error\n\n  const grupoIds = (insc ?? []).map((i) => i.grupo_id)\n  if (!grupoIds.length) return []\n\n  const { data: grupos } = await supabase\n    .from('grupos')\n    .select('id, nombre, nivel, dia, horario, disciplina')\n    .in('id', grupoIds)\n\n  const gruposMap = Object.fromEntries((grupos ?? []).map((g) => [g.id, g]))\n  return (insc ?? []).map((i) => ({ ...i, grupo: gruposMap[i.grupo_id] ?? null }))\n}\n\nexport async function getAsistencia(alumnoId) {\n  const { data, error } = await supabase\n    .from('asistencias')\n    .select('id, fecha, presente, grupo_id')\n    .eq('alumno_id', alumnoId)\n    .order('fecha', { ascending: false })\n    .limit(30)\n  if (error) throw error\n\n  const grupoIds = [...new Set((data ?? []).map((a) => a.grupo_id))]\n  if (!grupoIds.length) return []\n\n  const { data: grupos } = await supabase\n    .from('grupos')\n    .select('id, nombre')\n    .in('id', grupoIds)\n\n  const gruposMap = Object.fromEntries((grupos ?? []).map((g) => [g.id, g]))\n  return (data ?? []).map((a) => ({ ...a, grupo: gruposMap[a.grupo_id] ?? null }))\n}\n\nexport async function getEvaluaciones(alumnoId) {\n  const { data, error } = await supabase\n    .from('evaluaciones')\n    .select('id, fecha, nota, observaciones, grupo_id')\n    .eq('alumno_id', alumnoId)\n    .order('fecha', { ascending: false })\n  if (error) throw error\n\n  const grupoIds = [...new Set((data ?? []).map((e) => e.grupo_id))]\n  if (!grupoIds.length) return []\n\n  const { data: grupos } = await supabase\n    .from('grupos')\n    .select('id, nombre')\n    .in('id', grupoIds)\n\n  const gruposMap = Object.fromEntries((grupos ?? []).map((g) => [g.id, g]))\n  return (data ?? []).map((e) => ({ ...e, grupo: gruposMap[e.grupo_id] ?? null }))\n}\n",
  "src/services/auth.js": "import { supabase } from '../lib/supabase'\n\nexport async function loginByDni(dni, fechaNacimiento) {\n  const { data, error } = await supabase\n    .from('alumnos')\n    .select('id, nombre, apellido, dni, fecha_nacimiento')\n    .eq('dni', dni.trim())\n    .single()\n\n  if (error || !data) throw new Error('DNI no encontrado en el sistema.')\n  if (data.fecha_nacimiento !== fechaNacimiento)\n    throw new Error('La fecha de nacimiento no coincide.')\n\n  return { id: data.id, nombre: data.nombre, apellido: data.apellido }\n}\n",
  "src/lib/supabase.js": "import { createClient } from '@supabase/supabase-js'\n\nconst url = import.meta.env.VITE_SUPABASE_URL\nconst key = import.meta.env.VITE_SUPABASE_ANON_KEY\n\nexport const supabase = createClient(url, key)\n",
  "src/pages/Grupos.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getInscripciones } from '../services/portal'\nimport Spinner from '../components/ui/Spinner'\nimport { UsersRound, Clock, Calendar } from 'lucide-react'\n\nexport default function Grupos() {\n  const { alumno } = useAuth()\n  const [inscripciones, setInscripciones] = useState([])\n  const [loading, setLoading] = useState(true)\n\n  useEffect(() => {\n    getInscripciones(alumno.id).then(setInscripciones).finally(() => setLoading(false))\n  }, [alumno.id])\n\n  if (loading) return <Spinner className=\"mt-20\" />\n\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Mis grupos</h2>\n\n      {inscripciones.length === 0 ? (\n        <div className=\"flex flex-col items-center py-16 text-center\">\n          <div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\">\n            <UsersRound size={22} className=\"text-primary\" />\n          </div>\n          <p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin grupos activos</p>\n          <p className=\"text-xs text-[#A89FC8] mt-1\">Cuando te inscribas van a aparecer acá</p>\n        </div>\n      ) : (\n        <ul className=\"space-y-3\">\n          {inscripciones.map((i) => (\n            <li key={i.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] shadow-card overflow-hidden\">\n              <div className=\"p-1\" style={{ background: 'linear-gradient(135deg, #7C3AED, #A78BFA)' }} />\n              <div className=\"p-5\">\n                <div className=\"flex items-start justify-between mb-3\">\n                  <div>\n                    <p className=\"text-base font-bold text-[#1E1B4B]\">{i.grupo?.nombre ?? '—'}</p>\n                    <p className=\"text-xs text-[#A89FC8] mt-0.5\">{i.grupo?.nivel} · {i.grupo?.disciplina}</p>\n                  </div>\n                  <div className=\"w-9 h-9 bg-primary-light rounded-xl flex items-center justify-center shrink-0\">\n                    <UsersRound size={15} className=\"text-primary\" />\n                  </div>\n                </div>\n                <div className=\"flex gap-4 mt-3\">\n                  {i.grupo?.dia && (\n                    <div className=\"flex items-center gap-1.5 text-xs text-[#A89FC8]\">\n                      <Calendar size={12} />\n                      <span className=\"capitalize\">{i.grupo.dia}</span>\n                    </div>\n                  )}\n                  {i.grupo?.horario && (\n                    <div className=\"flex items-center gap-1.5 text-xs text-[#A89FC8]\">\n                      <Clock size={12} />\n                      <span>{i.grupo.horario}</span>\n                    </div>\n                  )}\n                </div>\n              </div>\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  )\n}\n",
  "src/pages/Evaluaciones.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getEvaluaciones } from '../services/portal'\nimport Spinner from '../components/ui/Spinner'\nimport { Star } from 'lucide-react'\n\nfunction notaColor(nota) {\n  if (nota >= 8) return 'text-teal'\n  if (nota >= 6) return 'text-primary'\n  return 'text-amber-500'\n}\n\nexport default function Evaluaciones() {\n  const { alumno } = useAuth()\n  const [evaluaciones, setEvaluaciones] = useState([])\n  const [loading, setLoading] = useState(true)\n\n  useEffect(() => {\n    getEvaluaciones(alumno.id).then(setEvaluaciones).finally(() => setLoading(false))\n  }, [alumno.id])\n\n  if (loading) return <Spinner className=\"mt-20\" />\n\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Evaluaciones</h2>\n\n      {evaluaciones.length === 0 ? (\n        <div className=\"flex flex-col items-center py-16 text-center\">\n          <div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\">\n            <Star size={22} className=\"text-primary\" />\n          </div>\n          <p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin evaluaciones aún</p>\n          <p className=\"text-xs text-[#A89FC8] mt-1\">Las notas del profesor van a aparecer acá</p>\n        </div>\n      ) : (\n        <ul className=\"space-y-3\">\n          {evaluaciones.map((e) => (\n            <li key={e.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card\">\n              <div className=\"flex items-start justify-between mb-2\">\n                <div>\n                  <p className=\"text-sm font-bold text-[#1E1B4B]\">{e.grupo?.nombre ?? '—'}</p>\n                  <p className=\"text-xs text-[#A89FC8] mt-0.5\">\n                    {new Date(e.fecha + 'T00:00:00').toLocaleDateString('es-AR', { day: 'numeric', month: 'long', year: 'numeric' })}\n                  </p>\n                </div>\n                {e.nota != null && (\n                  <div className=\"text-center\">\n                    <p className={`text-3xl font-black tabular-nums leading-none ${notaColor(e.nota)}`}>{e.nota}</p>\n                    <p className=\"text-[10px] text-[#A89FC8] mt-0.5\">/ 10</p>\n                  </div>\n                )}\n              </div>\n              {e.observaciones && (\n                <p className=\"text-xs text-[#6B5F9E] bg-[#F9F7FF] rounded-xl px-3 py-2.5 mt-3 leading-relaxed\">\n                  \"{e.observaciones}\"\n                </p>\n              )}\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  )\n}\n",
  "src/pages/Home.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getCuotas, getInscripciones } from '../services/portal'\nimport Badge from '../components/ui/Badge'\nimport Spinner from '../components/ui/Spinner'\nimport { CreditCard, UsersRound, AlertCircle, CheckCircle2 } from 'lucide-react'\n\nfunction estadoBadge(estado) {\n  if (estado === 'pagada') return <Badge color=\"teal\" dot>Pagada</Badge>\n  if (estado === 'vencida') return <Badge color=\"red\" dot>Vencida</Badge>\n  return <Badge color=\"yellow\" dot>Pendiente</Badge>\n}\n\nexport default function Home() {\n  const { alumno } = useAuth()\n  const [cuotas, setCuotas] = useState([])\n  const [grupos, setGrupos] = useState([])\n  const [loading, setLoading] = useState(true)\n\n  useEffect(() => {\n    async function cargar() {\n      try {\n        const [c, g] = await Promise.all([\n          getCuotas(alumno.id),\n          getInscripciones(alumno.id),\n        ])\n        setCuotas(c)\n        setGrupos(g)\n      } finally {\n        setLoading(false)\n      }\n    }\n    cargar()\n  }, [alumno.id])\n\n  const pendientes = cuotas.filter((c) => c.estado !== 'pagada').length\n  const ultimaCuota = cuotas[0]\n\n  if (loading) return <Spinner className=\"mt-20\" />\n\n  return (\n    <div className=\"px-4 py-5 space-y-5 animate-fade-up\">\n\n      {/* Saludo */}\n      <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card\"\n        style={{ background: 'linear-gradient(135deg, #2E1065, #7C3AED)' }}>\n        <p className=\"text-white/60 text-xs font-medium\">Hola,</p>\n        <h2 className=\"text-white font-bold text-xl font-display mt-0.5\">\n          {alumno.nombre} {alumno.apellido}\n        </h2>\n        <p className=\"text-white/50 text-xs mt-2\">\n          {grupos.length > 0\n            ? `Inscripta en ${grupos.length} grupo${grupos.length > 1 ? 's' : ''}`\n            : 'Sin grupos activos'}\n        </p>\n      </div>\n\n      {/* Resumen rápido */}\n      <div className=\"grid grid-cols-2 gap-3\">\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card\">\n          <div className=\"w-9 h-9 bg-primary-light rounded-xl flex items-center justify-center mb-3\">\n            <UsersRound size={16} className=\"text-primary\" />\n          </div>\n          <p className=\"text-2xl font-black text-primary\">{grupos.length}</p>\n          <p className=\"text-xs text-[#A89FC8] mt-0.5\">Grupos activos</p>\n        </div>\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card\">\n          <div className={`w-9 h-9 rounded-xl flex items-center justify-center mb-3 ${pendientes > 0 ? 'bg-amber-50' : 'bg-teal-light'}`}>\n            {pendientes > 0\n              ? <AlertCircle size={16} className=\"text-amber-500\" />\n              : <CheckCircle2 size={16} className=\"text-teal\" />}\n          </div>\n          <p className={`text-2xl font-black ${pendientes > 0 ? 'text-amber-500' : 'text-teal'}`}>{pendientes}</p>\n          <p className=\"text-xs text-[#A89FC8] mt-0.5\">Cuotas pendientes</p>\n        </div>\n      </div>\n\n      {/* Última cuota */}\n      {ultimaCuota && (\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card\">\n          <div className=\"flex items-center gap-2 mb-4\">\n            <div className=\"p-2 bg-primary-light rounded-xl\">\n              <CreditCard size={14} className=\"text-primary\" />\n            </div>\n            <p className=\"text-sm font-bold text-[#1E1B4B]\">Última cuota</p>\n          </div>\n          <div className=\"flex items-center justify-between\">\n            <div>\n              <p className=\"text-sm font-semibold text-[#1E1B4B] capitalize\">\n                {new Date(ultimaCuota.mes + '-01T00:00:00').toLocaleDateString('es-AR', { month: 'long', year: 'numeric' })}\n              </p>\n              <p className=\"text-xs text-[#A89FC8] mt-0.5\">\n                Vence: {ultimaCuota.fecha_vencimiento\n                  ? new Date(ultimaCuota.fecha_vencimiento + 'T00:00:00').toLocaleDateString('es-AR')\n                  : '—'}\n              </p>\n            </div>\n            <div className=\"text-right\">\n              <p className=\"text-lg font-black text-[#1E1B4B]\">\n                ${Number(ultimaCuota.monto).toLocaleString('es-AR')}\n              </p>\n              <div className=\"mt-1\">{estadoBadge(ultimaCuota.estado)}</div>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {/* Grupos */}\n      {grupos.length > 0 && (\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card\">\n          <p className=\"text-sm font-bold text-[#1E1B4B] mb-3\">Mis grupos</p>\n          <ul className=\"space-y-2\">\n            {grupos.map((i) => (\n              <li key={i.id} className=\"flex items-center gap-3 p-2.5 rounded-xl bg-[#F9F7FF]\">\n                <div className=\"w-8 h-8 bg-primary-light rounded-xl flex items-center justify-center shrink-0\">\n                  <UsersRound size={14} className=\"text-primary\" />\n                </div>\n                <div>\n                  <p className=\"text-sm font-semibold text-[#1E1B4B]\">{i.grupo?.nombre ?? '—'}</p>\n                  <p className=\"text-xs text-[#A89FC8]\">{i.grupo?.nivel} · {i.grupo?.dia} {i.grupo?.horario}</p>\n                </div>\n              </li>\n            ))}\n          </ul>\n        </div>\n      )}\n    </div>\n  )\n}\n",
  "src/pages/Login.jsx": "import { useState } from 'react'\nimport { useNavigate } from 'react-router-dom'\nimport { loginByDni } from '../services/auth'\nimport { useAuth } from '../context/AuthContext'\n\nexport default function Login() {\n  const [dni, setDni] = useState('')\n  const [fecha, setFecha] = useState('')\n  const [error, setError] = useState('')\n  const [loading, setLoading] = useState(false)\n  const { login } = useAuth()\n  const navigate = useNavigate()\n\n  async function handleSubmit(e) {\n    e.preventDefault()\n    setError('')\n    setLoading(true)\n    try {\n      const alumno = await loginByDni(dni, fecha)\n      login(alumno)\n      navigate('/home', { replace: true })\n    } catch (err) {\n      setError(err.message)\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  return (\n    <div className=\"min-h-svh flex flex-col items-center justify-center px-6 py-12\"\n      style={{ background: 'linear-gradient(160deg, #2E1065 0%, #3B0764 60%, #F4F2FF 100%)' }}>\n\n      {/* Logo */}\n      <div className=\"flex flex-col items-center mb-10\">\n        <div className=\"w-16 h-16 rounded-2xl bg-white/15 border border-white/25 flex items-center justify-center mb-4 backdrop-blur-sm\">\n          <span className=\"text-white font-black text-2xl font-display\">C</span>\n        </div>\n        <h1 className=\"text-white font-bold text-2xl tracking-wide font-display\">CREAR</h1>\n        <p className=\"text-white/50 text-xs tracking-widest uppercase mt-1\">Portal Familiar</p>\n      </div>\n\n      {/* Card */}\n      <div className=\"w-full max-w-sm bg-white rounded-3xl shadow-card-md p-7\">\n        <h2 className=\"text-[15px] font-bold text-[#1E1B4B] mb-1\">Ingresá a tu cuenta</h2>\n        <p className=\"text-xs text-[#A89FC8] mb-6\">Usá el DNI y la fecha de nacimiento del alumno</p>\n\n        <form onSubmit={handleSubmit} className=\"space-y-4\">\n          <div>\n            <label className=\"block text-xs font-semibold text-[#1E1B4B] mb-1.5\">DNI del alumno</label>\n            <input\n              type=\"text\" inputMode=\"numeric\" value={dni}\n              onChange={(e) => setDni(e.target.value)}\n              placeholder=\"Ej: 40123456\"\n              required\n              className=\"w-full px-4 py-3 rounded-xl border border-[#EDE9FE] bg-[#F9F7FF] text-sm text-[#1E1B4B] placeholder-[#C4B5FD] focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition\"\n            />\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-semibold text-[#1E1B4B] mb-1.5\">Fecha de nacimiento</label>\n            <input\n              type=\"date\" value={fecha}\n              onChange={(e) => setFecha(e.target.value)}\n              required\n              className=\"w-full px-4 py-3 rounded-xl border border-[#EDE9FE] bg-[#F9F7FF] text-sm text-[#1E1B4B] focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition\"\n            />\n          </div>\n\n          {error && (\n            <p className=\"text-xs text-red-600 bg-red-50 border border-red-200 rounded-xl px-4 py-2.5\">\n              {error}\n            </p>\n          )}\n\n          <button type=\"submit\" disabled={loading}\n            className=\"w-full py-3 rounded-xl bg-primary text-white font-semibold text-sm hover:bg-primary-dark active:scale-[.98] transition-all disabled:opacity-60 disabled:cursor-not-allowed shadow-card-md\">\n            {loading ? 'Verificando...' : 'Ingresar'}\n          </button>\n        </form>\n      </div>\n\n      <p className=\"text-white/25 text-[10px] mt-8 text-center\">\n        Academia de Danzas CREAR · Tesis 2025\n      </p>\n    </div>\n  )\n}\n",
  "src/pages/Asistencia.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getAsistencia } from '../services/portal'\nimport Spinner from '../components/ui/Spinner'\nimport { CalendarCheck, CalendarX } from 'lucide-react'\n\nexport default function Asistencia() {\n  const { alumno } = useAuth()\n  const [registros, setRegistros] = useState([])\n  const [loading, setLoading] = useState(true)\n\n  useEffect(() => {\n    getAsistencia(alumno.id).then(setRegistros).finally(() => setLoading(false))\n  }, [alumno.id])\n\n  if (loading) return <Spinner className=\"mt-20\" />\n\n  const presentes = registros.filter((r) => r.presente).length\n  const pct = registros.length > 0 ? Math.round((presentes / registros.length) * 100) : null\n\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Asistencia</h2>\n\n      {registros.length > 0 && (\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card flex items-center justify-between\">\n          <div>\n            <p className=\"text-xs text-[#A89FC8] font-medium\">Últimas {registros.length} clases</p>\n            <p className=\"text-2xl font-black text-primary mt-0.5\">{pct}%</p>\n            <p className=\"text-xs text-[#A89FC8]\">de asistencia</p>\n          </div>\n          <div className=\"text-right\">\n            <p className=\"text-sm font-semibold text-teal\">{presentes} presentes</p>\n            <p className=\"text-sm font-semibold text-red-500 mt-0.5\">{registros.length - presentes} ausentes</p>\n          </div>\n        </div>\n      )}\n\n      {registros.length === 0 ? (\n        <div className=\"flex flex-col items-center py-16 text-center\">\n          <div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\">\n            <CalendarCheck size={22} className=\"text-primary\" />\n          </div>\n          <p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin registros de asistencia</p>\n          <p className=\"text-xs text-[#A89FC8] mt-1\">Los registros aparecerán después de cada clase</p>\n        </div>\n      ) : (\n        <ul className=\"space-y-2\">\n          {registros.map((r) => (\n            <li key={r.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card flex items-center justify-between\">\n              <div className=\"flex items-center gap-3\">\n                <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${r.presente ? 'bg-teal-light' : 'bg-red-50'}`}>\n                  {r.presente\n                    ? <CalendarCheck size={15} className=\"text-teal\" />\n                    : <CalendarX size={15} className=\"text-red-500\" />}\n                </div>\n                <div>\n                  <p className=\"text-sm font-semibold text-[#1E1B4B]\">\n                    {new Date(r.fecha + 'T00:00:00').toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' })}\n                  </p>\n                  <p className=\"text-xs text-[#A89FC8]\">{r.grupo?.nombre ?? '—'}</p>\n                </div>\n              </div>\n              <span className={`text-xs font-bold ${r.presente ? 'text-teal' : 'text-red-500'}`}>\n                {r.presente ? 'Presente' : 'Ausente'}\n              </span>\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  )\n}\n",
  "src/pages/Pagos.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getCuotas } from '../services/portal'\nimport Badge from '../components/ui/Badge'\nimport Spinner from '../components/ui/Spinner'\nimport { CreditCard } from 'lucide-react'\n\nfunction badgeColor(estado) {\n  if (estado === 'pagada') return 'teal'\n  if (estado === 'vencida') return 'red'\n  return 'yellow'\n}\n\nfunction mesLabel(mes) {\n  return new Date(mes + '-01T00:00:00').toLocaleDateString('es-AR', { month: 'long', year: 'numeric' })\n}\n\nexport default function Pagos() {\n  const { alumno } = useAuth()\n  const [cuotas, setCuotas] = useState([])\n  const [loading, setLoading] = useState(true)\n\n  useEffect(() => {\n    getCuotas(alumno.id).then(setCuotas).finally(() => setLoading(false))\n  }, [alumno.id])\n\n  if (loading) return <Spinner className=\"mt-20\" />\n\n  const pendientes = cuotas.filter((c) => c.estado !== 'pagada')\n  const pagadas = cuotas.filter((c) => c.estado === 'pagada')\n\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Pagos y cuotas</h2>\n\n      {pendientes.length > 0 && (\n        <div>\n          <p className=\"text-xs font-semibold text-[#A89FC8] uppercase tracking-wider mb-2 px-1\">Pendientes</p>\n          <ul className=\"space-y-2\">\n            {pendientes.map((c) => (\n              <li key={c.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card flex items-center justify-between\">\n                <div className=\"flex items-center gap-3\">\n                  <div className=\"w-9 h-9 bg-amber-50 rounded-xl flex items-center justify-center shrink-0\">\n                    <CreditCard size={15} className=\"text-amber-500\" />\n                  </div>\n                  <div>\n                    <p className=\"text-sm font-semibold text-[#1E1B4B] capitalize\">{mesLabel(c.mes)}</p>\n                    <p className=\"text-xs text-[#A89FC8]\">\n                      Vence: {c.fecha_vencimiento\n                        ? new Date(c.fecha_vencimiento + 'T00:00:00').toLocaleDateString('es-AR')\n                        : '—'}\n                    </p>\n                  </div>\n                </div>\n                <div className=\"text-right\">\n                  <p className=\"text-sm font-black text-[#1E1B4B]\">${Number(c.monto).toLocaleString('es-AR')}</p>\n                  <Badge color={badgeColor(c.estado)} dot className=\"mt-1\">{c.estado}</Badge>\n                </div>\n              </li>\n            ))}\n          </ul>\n        </div>\n      )}\n\n      {pagadas.length > 0 && (\n        <div>\n          <p className=\"text-xs font-semibold text-[#A89FC8] uppercase tracking-wider mb-2 px-1\">Historial pagado</p>\n          <ul className=\"space-y-2\">\n            {pagadas.map((c) => (\n              <li key={c.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card flex items-center justify-between opacity-75\">\n                <div className=\"flex items-center gap-3\">\n                  <div className=\"w-9 h-9 bg-teal-light rounded-xl flex items-center justify-center shrink-0\">\n                    <CreditCard size={15} className=\"text-teal\" />\n                  </div>\n                  <div>\n                    <p className=\"text-sm font-semibold text-[#1E1B4B] capitalize\">{mesLabel(c.mes)}</p>\n                    <p className=\"text-xs text-[#A89FC8]\">\n                      Pagado: {c.fecha_pago\n                        ? new Date(c.fecha_pago + 'T00:00:00').toLocaleDateString('es-AR')\n                        : '—'}\n                    </p>\n                  </div>\n                </div>\n                <div className=\"text-right\">\n                  <p className=\"text-sm font-black text-[#1E1B4B]\">${Number(c.monto).toLocaleString('es-AR')}</p>\n                  <Badge color=\"teal\" dot className=\"mt-1\">pagada</Badge>\n                </div>\n              </li>\n            ))}\n          </ul>\n        </div>\n      )}\n\n      {cuotas.length === 0 && (\n        <div className=\"flex flex-col items-center py-16 text-center\">\n          <div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\">\n            <CreditCard size={22} className=\"text-primary\" />\n          </div>\n          <p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin cuotas registradas</p>\n          <p className=\"text-xs text-[#A89FC8] mt-1\">Cuando se generen van a aparecer acá</p>\n        </div>\n      )}\n    </div>\n  )\n}\n",
  "src/context/AuthContext.jsx": "import { createContext, useContext, useState, useCallback } from 'react'\n\nconst AuthContext = createContext(null)\n\nconst STORAGE_KEY = 'crear_portal_alumno'\n\nfunction loadSaved() {\n  try {\n    return JSON.parse(localStorage.getItem(STORAGE_KEY)) ?? null\n  } catch {\n    return null\n  }\n}\n\nexport function AuthProvider({ children }) {\n  const [alumno, setAlumno] = useState(loadSaved)\n\n  const login = useCallback((data) => {\n    localStorage.setItem(STORAGE_KEY, JSON.stringify(data))\n    setAlumno(data)\n  }, [])\n\n  const logout = useCallback(() => {\n    localStorage.removeItem(STORAGE_KEY)\n    setAlumno(null)\n  }, [])\n\n  return (\n    <AuthContext.Provider value={{ alumno, login, logout }}>\n      {children}\n    </AuthContext.Provider>\n  )\n}\n\nexport function useAuth() {\n  return useContext(AuthContext)\n}\n",
  "index.html": "<!doctype html>\n<html lang=\"es\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\" />\n    <meta name=\"theme-color\" content=\"#7C3AED\" />\n    <meta name=\"apple-mobile-web-app-capable\" content=\"yes\" />\n    <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\" />\n    <meta name=\"apple-mobile-web-app-title\" content=\"CREAR\" />\n    <title>CREAR — Portal Familiar</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;1,400&display=swap\" rel=\"stylesheet\" />\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.jsx\"></script>\n  </body>\n</html>\n",
  "vite.config.js": "import { defineConfig } from 'vite'\nimport react from '@vitejs/plugin-react'\nimport { VitePWA } from 'vite-plugin-pwa'\n\nexport default defineConfig({\n  plugins: [\n    react(),\n    VitePWA({\n      registerType: 'autoUpdate',\n      includeAssets: ['logo.png'],\n      manifest: {\n        name: 'CREAR — Portal Familiar',\n        short_name: 'CREAR',\n        description: 'Información para alumnos y familias de la Academia de Danzas CREAR',\n        theme_color: '#7C3AED',\n        background_color: '#F4F2FF',\n        display: 'standalone',\n        orientation: 'portrait',\n        start_url: '/',\n        icons: [\n          { src: 'pwa-192.png', sizes: '192x192', type: 'image/png' },\n          { src: 'pwa-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' },\n        ],\n      },\n      workbox: {\n        globPatterns: ['**/*.{js,css,html,ico,png,svg}'],\n      },\n    }),\n  ],\n})\n",
  "tailwind.config.js": "/** @type {import('tailwindcss').Config} */\nexport default {\n  content: ['./index.html', './src/**/*.{js,jsx}'],\n  theme: {\n    extend: {\n      colors: {\n        primary: '#7C3AED',\n        'primary-dark': '#6D28D9',\n        'primary-light': '#EDE9FE',\n        'primary-subtle': '#F4F2FF',\n        teal: '#0D9488',\n        'teal-dark': '#0F766E',\n        'teal-light': '#CCFBF1',\n      },\n      fontFamily: {\n        sans: ['Inter', 'system-ui', 'sans-serif'],\n        display: ['\"Playfair Display\"', 'Georgia', 'serif'],\n      },\n      boxShadow: {\n        card: '0 1px 4px 0 rgb(0 0 0 / 0.06)',\n        'card-md': '0 4px 16px 0 rgb(124 58 237 / 0.12)',\n      },\n      animation: {\n        'fade-up': 'fadeUp 0.3s ease-out both',\n      },\n      keyframes: {\n        fadeUp: {\n          '0%': { opacity: '0', transform: 'translateY(8px)' },\n          '100%': { opacity: '1', transform: 'translateY(0)' },\n        },\n      },\n    },\n  },\n  plugins: [],\n}\n\n",
  "postcss.config.js": "export default {\n  plugins: {\n    tailwindcss: {},\n    autoprefixer: {},\n  },\n}\n",
  ".gitignore": "node_modules\ndist\n.env\n.env.local\n",
  ".env.example": "VITE_SUPABASE_URL=https://umyxrehjchxlxtdibaii.supabase.co\nVITE_SUPABASE_ANON_KEY=sb_publishable_9IVvZSsjFPvtak80-_ZGEg_nKYn95vr\n",
  "package.json": "{\n  \"name\": \"portal-crear\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"lint\": \"eslint .\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"@supabase/supabase-js\": \"^2.105.4\",\n    \"lucide-react\": \"^1.14.0\",\n    \"react\": \"^19.2.5\",\n    \"react-dom\": \"^19.2.5\",\n    \"react-router-dom\": \"^7.15.0\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^10.0.1\",\n    \"@types/react\": \"^19.2.14\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^6.0.1\",\n    \"autoprefixer\": \"^10.5.0\",\n    \"eslint\": \"^10.2.1\",\n    \"eslint-plugin-react-hooks\": \"^7.1.1\",\n    \"eslint-plugin-react-refresh\": \"^0.5.2\",\n    \"globals\": \"^17.5.0\",\n    \"postcss\": \"^8.5.14\",\n    \"tailwindcss\": \"^3.4.19\",\n    \"vite\": \"^8.0.10\",\n    \"vite-plugin-pwa\": \"^1.3.0\"\n  }\n}\n"
}

for path, content in FILES.items():
    full = os.path.join(BASE, path)
    os.makedirs(os.path.dirname(full) or BASE, exist_ok=True)
    with open(full, "w", encoding="utf-8") as f:
        f.write(content)

